solution.solution.cpp:
#include <algorithm>
#include <vector>

template <typename T>
void moveItem(std::vector<T>& items, int from, int to)
{
    const int n{ static_cast<int>(items.size()) };
    if (from < 0 || to < 0 || from >= n || to >= n || from == to) return;
    if (from < to) std::rotate(items.begin() + from, items.begin() + from + 1, items.begin() + to + 1);
    else std::rotate(items.begin() + to, items.begin() + from, items.begin() + from + 1);
}

unitTests:
using S = std::vector<std::string>;
TEST("down") { S v{ "A", "B", "C", "D", "E" }; moveItem(v, 1, 3); CHECK_EQ(v, (S{ "A", "C", "D", "B", "E" })); }
TEST("up") { S v{ "A", "B", "C", "D", "E" }; moveItem(v, 4, 0); CHECK_EQ(v, (S{ "E", "A", "B", "C", "D" })); }
TEST("neighbours") { S v{ "A", "B", "C" }; moveItem(v, 0, 1); CHECK_EQ(v, (S{ "B", "A", "C" })); moveItem(v, 2, 1); CHECK_EQ(v, (S{ "B", "C", "A" })); }
TEST("nothing to do") { S v{ "A", "B" }; moveItem(v, 1, 1); moveItem(v, -1, 0); moveItem(v, 0, 5); CHECK_EQ(v, (S{ "A", "B" })); }
TEST("ints") { std::vector<int> v{ 1, 2, 3, 4 }; moveItem(v, 0, 3); CHECK_EQ(v, (std::vector<int>{ 2, 3, 4, 1 })); }

